# ── Postfix evaluator tests ──────────────────────────────────────────

def test_simple_addition():
    assert circular_buffer([3, 4, "+"]) == 7.0


def test_simple_subtraction():
    assert circular_buffer([10, 3, "-"]) == 7.0


def test_simple_multiplication():
    assert circular_buffer([5, 6, "*"]) == 30.0


def test_simple_division():
    assert circular_buffer([20, 4, "/"]) == 5.0


def test_complex_expression():
    # (3 + 4) * (5 - 2) = 21
    assert circular_buffer([3, 4, "+", 5, 2, "-", "*"]) == 21.0


def test_expression_with_exponent():
    # 2 ** 10 = 1024
    assert circular_buffer([2, 10, "**"]) == 1024.0


def test_floor_division():
    assert circular_buffer([17, 5, "//"]) == 3.0


def test_modulo():
    assert circular_buffer([17, 5, "%"]) == 2.0


def test_unary_abs():
    assert circular_buffer([-5, "abs"]) == 5.0


def test_unary_neg():
    assert circular_buffer([3, "neg"]) == -3.0


def test_unary_sqrt():
    assert circular_buffer([16, "sqrt"]) == 4.0


def test_mixed_operations():
    # (2 + 3) * sqrt(16) = 20
    assert circular_buffer([2, 3, "+", 16, "sqrt", "*"]) == 20.0


