def test_nested_expression():
    # ((2 + 3) * 4) - (10 / 2) = 15
    assert circular_buffer([2, 3, "+", 4, "*", 10, 2, "/", "-"]) == 15.0


def test_negative_result():
    assert circular_buffer([3, 10, "-"]) == -7.0


