    with pytest.raises(ValueError, match="division by zero"):
        circular_buffer([1, 0, "/"])


def test_floor_division_by_zero_raises():
    import pytest
    with pytest.raises(ValueError, match="division by zero"):
        circular_buffer([1, 0, "//"])


def test_modulo_by_zero_raises():
    import pytest
    with pytest.raises(ValueError, match="division by zero"):
        circular_buffer([1, 0, "%"])


