    import pytest
    with pytest.raises(ValueError, match="unknown operator"):
        circular_buffer([1, 2, "&"])


def test_sqrt_of_negative_raises():
    import pytest
    with pytest.raises(ValueError, match="math error"):
        circular_buffer([-1, "sqrt"])


